/* global window,document,process,console,setTimeout,localStorage,URL */
import {chromium} from '@playwright/test';
import {writeFile,mkdir} from 'node:fs/promises';
import path from 'node:path';
import {fileURLToPath,pathToFileURL} from 'node:url';
import {serveRun,loadRun} from './runner.mjs';
const ROOT=fileURLToPath(new URL('../../',import.meta.url));
/**
 * TEST ONLY: the original pinned 3D engine is NOT mocked. Deaths are
 * deliberately generated by invoking the genuine native kill/spawn methods,
 * rather than claiming human natural combat. The ad callback is FAKE FIXTURE,
 * NOT an actual TapTap ad. Verify the real in-product shell recovers.
 */
export async function probeNativeRevive(runId){
  const base=path.join(ROOT,'runs');
  const {root,run}=await loadRun(base,runId);
  if(run.theme!=='cf-transport-ship')throw Error('Original pinned 3D game required');
  const server=await serveRun(base,runId,0);
  const browser=await chromium.launch({headless:true,args:['--enable-unsafe-swiftshader']});
  const context=await browser.newContext({viewport:{width:667,height:375},hasTouch:true,isMobile:true});
  await context.addInitScript(()=>{
    // Actual TapTap account permission remains unavailable; this isolated test
    // only substitutes the ad **host callback**, never checked in as product data.
    const fixture={status:1,source:'check_ads_status',appId:'QA_HOST_ONLY',
      spaceId:'QA_HOST_ONLY',screenOrientation:1};
    Object.defineProperty(window,'__PLATFORM_META__',{
      configurable:true,get:()=>fixture,set:()=>{}});
    const key='h5-mobile:h5-cf-challenges-20261013:cf-transport-ship:v1';
    localStorage.setItem(key,JSON.stringify({version:1,gameId:'cf-transport-ship',
      progress:{version:1,best:0,bank:0,rounds:1,nextRoundId:2,
        lastRewardedRound:0,assistTokens:0}}));
    window.__qaAdsShown=0;
    window.__qaAdNextResult='cancelled';
    window.tap={createRewardedVideoAd:()=>{
      const close=new Set(),errors=new Set();
      return {
        onClose:cb=>close.add(cb),offClose:cb=>close.delete(cb),
        onError:cb=>errors.add(cb),offError:cb=>errors.delete(cb),
        load:async()=>{},show:async()=>{
          window.__qaAdsShown++;
          setTimeout(()=>{for(const cb of close)
            cb({isEnded:window.__qaAdNextResult==='completed'});},90);
        }
      };
    }};
  });
  const page=await context.newPage();
  const checks=[],errors=[];
  const check=(name,passed,detail)=>checks.push({name,passed:passed===true,detail});
  page.on('pageerror',e=>errors.push(e.message));
  const snapshot=()=>page.evaluate(()=>{
    const g=window.__H5NativeGame,p=g?.player,el=document.getElementById('mobile-kit');
    return {phase:el?.dataset.phase,live:!!g?.playing,nativePaused:g?.paused,
      nativeEnded:g?.ended,playerAlive:p?.alive,nativeHp:p?.hp,
      nativeRespawnSeconds:p?.respawnT,nativeDeaths:p?.stats?.d,
      nativeSeconds:g?.time,shownAds:window.__qaAdsShown,
      notice:document.getElementById('mk-notice')?.textContent,
      adsVisible:document.getElementById('mk-revive-actions')?.hidden===false};
  });
  try{
    await page.goto('http://127.0.0.1:'+server.address().port);
    await page.waitForSelector('#mobile-kit[data-loaded="true"]',{timeout:45000});
    // Real elapsed boot time is mandatory; no clock hacks or bypass of 60s gate.
    // Test budget: one extra minute of READY screen, not fake simulation time.
    await page.waitForTimeout(62500);
    await page.locator('#mk-challenges [data-challenge-id="defense"]').tap();
    await page.locator('#mk-start').tap();
    await page.waitForSelector('#mobile-kit[data-native-phase="running"]',{timeout:30000});
    const before=await snapshot();
    const nativeActions=await page.evaluate(()=>{
      const g=window.__H5NativeGame,p=g.player;
      const foe=g.actors.find(a=>a.team!==p.team&&a.alive);
      if(!foe||!p||typeof g.kill!=='function'||typeof g.spawnActor!=='function')
        return {error:'source kill/spawn not present'};
      // Native functions, not fabricated player.stats modifications:
      for(let n=0;n<3;n++){
        if(!p.alive)g.spawnActor(p);
        g.kill(p,foe,'ak47',false,false,{x:1,z:0});
      }
      return {deaths:p.stats.d,respawnSeconds:p.respawnT,alive:p.alive,
        gtime:g.time,source:'NATIVE_KILL_AND_SPAWN_SYNTHETIC'};
    });
    await page.waitForSelector('#mobile-kit[data-phase="revive"]',{timeout:15000});
    const prompt=await snapshot();
    check('genuine-engine-fatal-lives-trigger-optional-offer',
      before.phase==='running'&&nativeActions.deaths===3&&
      nativeActions.alive===false&&prompt.phase==='revive'&&
      prompt.adsVisible===true&&prompt.nativePaused===true,
      {before,nativeActions,prompt});
    await page.locator('#mk-revive-ad').tap();
    await page.waitForTimeout(320);
    const cancelled=await snapshot();
    check('fake-ad-cancel-does-not-revive-and-keeps-decline-visible',
      cancelled.shownAds===1&&cancelled.phase==='revive'&&
      cancelled.nativePaused===true&&cancelled.nativeDeaths===3&&
      cancelled.adsVisible===true,cancelled);
    await page.evaluate(()=>{window.__qaAdNextResult='completed';});
    await page.locator('#mk-revive-ad').tap();
    await page.waitForTimeout(400);
    const resumed=await snapshot();
    check('completed-fixture-only-video-resumes-original-game-timer',
      resumed.shownAds===2&&resumed.phase==='running'&&
      resumed.nativePaused===false&&resumed.nativeDeaths===3,
      resumed);
    await page.waitForFunction(()=>window.__H5NativeGame?.player?.alive===true,
      {timeout:12000});
    const respawned=await snapshot();
    check('native-four-second-death-respawn-resumes-without-forged-health',
      respawned.playerAlive===true&&respawned.nativeHp>0&&
      respawned.nativeDeaths===3&&respawned.phase==='running',
      respawned);
    await page.evaluate(()=>{
      const g=window.__H5NativeGame,p=g.player,
        foe=g.actors.find(a=>a.team!==p.team&&a.alive);
      g.kill(p,foe,'ak47',false,false,{x:1,z:0});
    });
    await page.waitForSelector('#mobile-kit[data-phase="finished"]',{timeout:12000});
    const defeated=await snapshot();
    check('additional-real-native-death-cannot-trigger-second-ad',
      defeated.phase==='finished'&&defeated.shownAds===2&&
      defeated.adsVisible===false&&defeated.nativeDeaths===4,
      defeated);
    const resultScreen=await page.locator('#mk-fps-award').innerText();
    check('ad-rewarded-extra-life-never-mints-unassisted-three-stars',
      resultScreen.includes('无三星与个人最速记录'),
      {award:resultScreen});
  }catch(e){errors.push(String(e.stack||e));}finally{
    await browser.close();await new Promise(res=>server.close(res));
  }
  const report={scope:'CF_V10_REAL_NATIVE_SYNTHETIC_DEATH_SDK_FIXTURE_ONLY',
    passed:errors.length===0&&checks.every(c=>c.passed),
    caveat:'Native kill/spawn is deliberately invoked by test; ad response is MOCK. No natural combat or real TapTap ad claimed.',
    checks,errors};
  await mkdir(root,{recursive:true});
  await writeFile(path.join(root,'cf-v10-native-revive-browser.json'),JSON.stringify(report,null,2));
  return report;
}
if(process.argv[1]&&pathToFileURL(path.resolve(process.argv[1])).href===import.meta.url){
  const result=await probeNativeRevive(process.argv[2]);
  console.log(JSON.stringify(result,null,2));if(!result.passed)process.exitCode=1;
}
